fn clip(arr: &Vec<i8>, min_val: i8, max_val: i8) -> Vec<i8> {
    if min_val <= max_val {
        // Normal case: clip each element to the range [min_val, max_val]
        arr.iter().map(|&x| x.clamp(min_val, max_val)).collect()
    } else {
        // Special case: min_val > max_val, return all max_val
        vec![max_val; arr.len()]
    }
}